import{_ as t,o as a,c as o,ag as d}from"./chunks/framework.BPmc_f4o.js";const u=JSON.parse('{"title":"Mutation model","description":"Normative specification of instant versus staged mutation paths, entity lifecycle states, commit drain ordering, and visibility guarantees","frontmatter":{"description":"Normative specification of instant versus staged mutation paths, entity lifecycle states, commit drain ordering, and visibility guarantees","outline":"deep"},"headers":[],"relativePath":"ecs/mutation-model.md","filePath":"ecs/mutation-model.md"}'),s={name:"ecs/mutation-model.md"};function r(n,e,i,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /ecs/mutation-model.md for this page in Markdown format</div><h1 id="mutation-model" tabindex="-1">Mutation model <a class="header-anchor" href="#mutation-model" aria-label="Permalink to &quot;Mutation model&quot;">​</a></h1><p>This page is the normative specification of how entity and component mutations execute in Tecs: when a change applies, what readers observe in between, and the guarantees every mutation path provides. Other pages describe the individual APIs; when they disagree with this page, this page wins.</p><h2 id="execution-paths" tabindex="-1">Execution paths <a class="header-anchor" href="#execution-paths" aria-label="Permalink to &quot;Execution paths&quot;">​</a></h2><p>Tecs executes mutations through several specialized paths:</p><table tabindex="0"><thead><tr><th>Path</th><th>APIs</th><th>How it applies</th></tr></thead><tbody><tr><td>Instant</td><td><code>spawn</code> / <code>set</code> / <code>remove</code> / <code>despawn</code> at scope depth 0</td><td>In place, before the call returns</td></tr><tr><td>Staged</td><td>the same APIs inside a <a href="/ecs/world.html#deferred-operations">deferred scope</a></td><td>Staged, applied by the commit drain</td></tr><tr><td>Batch</td><td><code>batchSpawn</code> / <code>batchSpawnAt</code> / <code>batchSet</code> / <code>batchRemove</code> / <code>batchDespawn</code></td><td>Stage internally; drain when the outermost scope closes</td></tr><tr><td>Bundle</td><td><code>bundle:spawn</code> / <code>world:spawnBundle</code></td><td>Codegen-specialized spawn; instant or staged by scope depth</td></tr><tr><td>Explicit id</td><td><code>spawnAt</code>, <code>batchSpawnAt</code>, snapshot load</td><td>Staged placement at caller-supplied ids</td></tr><tr><td>Sparse relationship</td><td><code>set</code> / <code>remove</code> of sparse relationship instances</td><td>External store; staged writes commit at the end of the drain</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">The convergence rule</p><p>Every path produces the same observable post-commit state for the same logical operations. The instant path is an optimization of the staged path, not a separate semantic.</p><p>This rule is load-bearing because the instant path reroutes to the staged path silently: when the target entity is already part of the current transaction, when <code>OnSpawn</code> observers exist (spawn), when despawn cleanup, cascade deletes, or <code>OnDespawn</code> observers are involved (despawn), and for components whose behavior requires staging (sparse relationships). Callers cannot predict which path runs, so any semantic difference between paths is a bug.</p></div><h2 id="entity-lifecycle-states" tabindex="-1">Entity lifecycle states <a class="header-anchor" href="#entity-lifecycle-states" aria-label="Permalink to &quot;Entity lifecycle states&quot;">​</a></h2><p>Within one transaction (the window between the first staged mutation and its commit), every entity id is in exactly one of four states:</p><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td>Committed</td><td>Placed in an archetype; no staged changes this transaction</td></tr><tr><td>Staged spawn</td><td>Spawned this transaction; not yet placed in an archetype</td></tr><tr><td>Staged mutate</td><td>Committed entity with a staged structural change (component add or remove)</td></tr><tr><td>Staged despawn</td><td>Despawn requested this transaction; row not yet removed</td></tr></tbody></table><p>All staged state resets when the transaction commits. Reads behave per state:</p><table tabindex="0"><thead><tr><th>State</th><th><strong><code>isAlive</code></strong></th><th><strong><code>get</code> / <code>has</code></strong></th><th><strong>Queries</strong></th></tr></thead><tbody><tr><td><strong>Committed</strong></td><td><code>true</code></td><td>committed value</td><td>matches</td></tr><tr><td><strong>Staged spawn</strong></td><td><code>false</code> until commit</td><td><code>nil</code> / <code>false</code></td><td>no match until commit</td></tr><tr><td><strong>Staged mutate</strong></td><td><code>true</code></td><td>committed structure (see <a href="#visibility-inside-a-scope">Visibility</a>)</td><td>committed archetype</td></tr><tr><td><strong>Staged despawn</strong></td><td><code>true</code> until commit</td><td>committed value</td><td>matches until commit</td></tr></tbody></table><h2 id="operations-by-state" tabindex="-1">Operations by state <a class="header-anchor" href="#operations-by-state" aria-label="Permalink to &quot;Operations by state&quot;">​</a></h2><p>Staged semantics; the instant path converges to the same post-commit result.</p><table tabindex="0"><thead><tr><th>Operation</th><th>Committed</th><th>Staged spawn</th><th>Staged mutate</th><th>Staged despawn</th></tr></thead><tbody><tr><td><strong><code>set</code></strong></td><td>Writes the value in place when the archetype already has the component; otherwise stages a structural move</td><td>Updates the staged archetype and staged value</td><td>Restages the move target; the value applies at commit</td><td>Ignored</td></tr><tr><td><strong><code>remove</code></strong></td><td>Stages a move out (no-op when the component is absent)</td><td>Shrinks the staged archetype</td><td>Restages the move target</td><td>Ignored</td></tr><tr><td><strong><code>despawn</code></strong></td><td>Records despawn, runs component cleanup, emits <code>OnDespawn</code>, queues row removal</td><td>Cancels the spawn; nothing is placed (<code>OnDespawn</code> still fires)</td><td>Cancels the staged move and queues removal</td><td>Ignored (double-despawn guard)</td></tr></tbody></table><p><code>spawnAt</code> requires the id to not be live; it revives ids sitting on the free stack and reconciles the allocator. Passing a live id is caller error with undefined results.</p><h2 id="the-commit-drain" tabindex="-1">The commit drain <a class="header-anchor" href="#the-commit-drain" aria-label="Permalink to &quot;The commit drain&quot;">​</a></h2><p>When the outermost scope closes on a dirty world, the transaction drains. The drain runs in <strong>waves</strong> over the dirty archetype list, and each wave applies phases in this order:</p><ol><li><strong>Despawns</strong>: staged despawns remove rows (and whole-archetype clears from <code>batchDespawn</code> truncate), so later phases can reuse the space.</li><li><strong>Spawns</strong>: per dirty archetype, in this order: bundle spawn queues, <code>batchSpawn</code> queues, <code>batchSpawnAt</code> queues, then per-entity staged spawns.</li><li><strong>Moves</strong>: staged component adds and removes relocate rows between archetypes, applying staged values onto the destination rows.</li></ol><p>Observers and query callbacks fire during these phases. Mutations they stage mark new archetypes dirty and form the next wave. When a wave completes with no new structural work, two one-shot phases run:</p><ol start="4"><li><strong>Batch mutations</strong>: <code>batchSet</code> / <code>batchRemove</code> entries apply in the order the calls were made.</li><li><strong>Sparse relationship commits</strong>: staged sparse writes flush to their relationship stores.</li></ol><p>Phases 4 and 5 can stage new structural work, which starts another wave. The drain loops to a fixed point, bounded at 64 iterations; exceeding the bound raises <code>&quot;_drain exceeded MAX_DRAIN_ITERATIONS; likely an observer cascade with no fixed point&quot;</code>.</p><p><strong>Ordering guarantees:</strong></p><ul><li>Despawns apply before spawns within a wave; rows freed by despawns are reusable by spawns in the same wave.</li><li>For one entity and one component, the last staged write wins at commit.</li><li>Staged operations that net out structurally (remove then re-add of the same component) leave the entity&#39;s row in place and apply the final value there; no query callbacks fire because the archetype never changes.</li><li>A staged despawn cancels every other staged operation for that entity: staged spawns are never placed, staged moves never run, and staged sparse writes are discarded.</li><li>Sparse writes staged by an entity that despawns in the same transaction are discarded, including when the slot is recycled mid-transaction.</li></ul><h2 id="who-holds-a-scope" tabindex="-1">Who holds a scope <a class="header-anchor" href="#who-holds-a-scope" aria-label="Permalink to &quot;Who holds a scope&quot;">​</a></h2><p>Scope depth decides staging, and iteration is what usually raises it:</p><ul><li>A <a href="/ecs/queries/">query</a> iterator pushes a scope on its first step and pops it when the loop runs out of archetypes, so mutations made inside the loop stage and apply after it.</li><li>Query callbacks run inside the drain that triggered them, which holds a scope for its whole duration.</li><li>Each batch call holds a scope for the duration of the call.</li><li><code>world:defer()</code> and <code>world:commit()</code> open and close one explicitly.</li></ul><p>This makes leaving an archetype-level <code>query:iter()</code> loop early a real hazard: the pop that ends the loop never runs, the world stays deferred, and every later mutation stages silently instead of applying. Use <code>query:iter()</code> for loops that run to exhaustion; when a loop may <code>break</code> or return early, take a <code>query:cursor()</code> and call <code>cursor:close()</code> after the loop or immediately before returning. Closing a cursor is safe before iteration, after natural exhaustion, and more than once.</p><p><code>world:unwind()</code> is the recovery path for the case nothing else covers: a throw part way through a frame skips the pop that ends the loop&#39;s scope. <code>unwind</code> closes every open scope and drains what they staged; at depth zero it is the same drain <code>commit</code> performs. <code>world:update</code> calls it at the start of every frame, so a frame that threw cannot leave the frames after it staging. Popping a query scope is clamped at zero, so a cursor closed after an unwind cannot push the depth negative.</p><h2 id="visibility-inside-a-scope" tabindex="-1">Visibility inside a scope <a class="header-anchor" href="#visibility-inside-a-scope" aria-label="Permalink to &quot;Visibility inside a scope&quot;">​</a></h2><ul><li>Entity ids returned by any spawn path are valid immediately: they accept <code>set</code> / <code>remove</code> / <code>despawn</code> and resolve correctly at commit.</li><li><strong>Structure never appears early.</strong> Component adds, removes, spawns, and despawns are invisible to <code>get</code>, <code>has</code>, <code>isAlive</code>, and queries until the drain applies them.</li><li><strong>Values can appear early.</strong> A <code>set</code> of a component the entity already has, on an entity with no staged structural change, writes through to the column immediately at any scope depth. Once the entity has a staged structural change, subsequent <code>set</code> calls stage and apply at commit. Either way the post-commit value follows last-write-wins; only mid-scope reads can tell the difference.</li><li>Inside query callbacks (<code>onEntitiesAdded</code> / <code>onEntitiesRemoved</code>), reading the passed archetype&#39;s columns over the given row range is always current. See <a href="/ecs/queries/callbacks.html">Query callbacks</a>.</li></ul><h2 id="dead-and-stale-handles" tabindex="-1">Dead and stale handles <a class="header-anchor" href="#dead-and-stale-handles" aria-label="Permalink to &quot;Dead and stale handles&quot;">​</a></h2><p>Entity ids carry a generation; a recycled slot rejects handles from its previous entity. The policy is identical at every scope depth and on every path:</p><table tabindex="0"><thead><tr><th>Operation on a dead or stale id</th><th>Behavior</th></tr></thead><tbody><tr><td><code>get</code> / <code>getMut</code></td><td>Returns <code>nil</code></td></tr><tr><td><code>has</code></td><td>Returns <code>false</code></td></tr><tr><td><code>isAlive</code></td><td>Returns <code>false</code></td></tr><tr><td><code>markComponentDirty</code></td><td>No-op</td></tr><tr><td><code>set</code></td><td>Raises <code>&quot;Entity ID not found: &lt;id&gt;&quot;</code></td></tr><tr><td><code>remove</code></td><td>No-op</td></tr><tr><td><code>despawn</code></td><td>No-op</td></tr></tbody></table><h2 id="event-timing" tabindex="-1">Event timing <a class="header-anchor" href="#event-timing" aria-label="Permalink to &quot;Event timing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th><code>OnSpawn</code></th><th><code>OnDespawn</code></th></tr></thead><tbody><tr><td><strong><code>spawn</code>, <code>spawnAt</code></strong></td><td>Once per entity</td><td>n/a</td></tr><tr><td><strong><code>despawn</code></strong></td><td>n/a</td><td>Once per entity, to the entity address and the global address</td></tr><tr><td><strong><code>batchSpawn</code>, <code>batchSpawnAt</code></strong></td><td>Not emitted, by design; use the fill callback or a query&#39;s <code>onEntitiesAdded</code></td><td>n/a</td></tr><tr><td><strong><code>batchDespawn</code></strong></td><td>n/a</td><td>Once per entity</td></tr><tr><td><strong>Bundle spawn</strong></td><td>Once per entity, same contract as <code>spawn</code></td><td>n/a</td></tr></tbody></table><ul><li><code>OnSpawn</code> is emitted during the spawn call while the entity is staged: <code>isAlive</code> returns <code>false</code>, and mutations made by observers stage against the pending entity.</li><li><code>OnDespawn</code> is emitted during the despawn call, before physical removal: <code>isAlive</code> returns <code>true</code>, components are still readable through <code>get</code>, and the entity still matches queries. After the fan-out, all observers on the entity&#39;s address are cleared so they never fire for a future entity recycled into the same slot.</li><li>Query callbacks fire per contiguous row range when rows are physically added or removed: inline on the instant path, during the drain otherwise.</li></ul><h2 id="dirty-state" tabindex="-1">Dirty state <a class="header-anchor" href="#dirty-state" aria-label="Permalink to &quot;Dirty state&quot;">​</a></h2><p>Dirty bits are per archetype and per component, and the renderer is the consumer that makes them matter. The extractor installs a system named <code>tecs.SyncRenderState</code> in the <code>RenderFirst</code> phase, so it runs inside <code>world:update</code>. It walks the archetypes its renderable query matches and rewrites a run into GPU staging only when that archetype&#39;s <code>Transform</code>, <code>Tint</code>, <code>Sprite</code>, <code>Material</code>, <code>Clip</code> or sprite-sheet <code>Pivot</code> column is dirty, when its rows moved, or when interpolation moved the drawn position. An archetype nothing touched costs the comparison and nothing else, which is what makes a large world affordable. <code>renderer.rewritten</code> reports how many rows the last frame rewrote.</p><p>The mutation paths maintain the bits; the rules below are what a caller still owes.</p><ul><li>Read through <code>archetype:get</code> / <code>world:get</code>, write through <code>archetype:getMut</code> / <code>world:getMut</code>, which marks the component&#39;s column dirty on the archetype. Never call <code>getMut</code> in a loop that might not write: taking it to read marks the component dirty on every archetype every frame, and the extractor then rewrites the whole scene.</li><li>The render components that carry data are FFI components, so a write through <code>world:get</code> goes straight into C memory and marks nothing. Follow it with <code>world:markComponentDirty(id, Component)</code> or the row is never re-synced.</li><li>Dirty bits clear at the end of each <code>world:update</code>, after the pipeline finishes, which is after extraction has read them.</li><li><code>world:batchSpawn</code> writes only the <code>requires</code>-supplied defaults before handing you the row range; component constructors and their defaults do not run. Set every field you depend on in the callback.</li></ul><p>See <a href="/ecs/components/dirty-tracking.html">Dirty tracking</a> for the reader side.</p><h2 id="obligations-of-every-mutation-path" tabindex="-1">Obligations of every mutation path <a class="header-anchor" href="#obligations-of-every-mutation-path" aria-label="Permalink to &quot;Obligations of every mutation path&quot;">​</a></h2><p>Every path that spawns entities or changes component membership honors all of the following. This is the conformance checklist for adding or changing a mutation path.</p><ul><li><strong><code>requires</code> closure</strong>: adding a component pulls its transitive <a href="/ecs/components/"><code>requires</code></a> closure into the same archetype transition, writing default values for components the entity lacks. User-supplied values win over required defaults.</li><li><strong>Wildcard containers</strong>: setting a dense relationship instance also adds its container component, so wildcard queries match.</li><li><strong>State auto-tagging</strong>: spawn-family paths add the active <a href="/ecs/states.html">state component</a>; <code>set</code> / <code>remove</code> never do.</li><li><strong><code>Key</code> claiming</strong>: a key is claimed (and duplicate live keys rejected) before the entity becomes visible, and released on despawn. Bulk spawn paths reject <code>Key</code> up front because keys are per entity.</li><li><strong>Scalar unwrapping</strong>: columns store raw scalar values; wrapper instances are unwrapped at the API boundary.</li><li><strong>Tags</strong>: tag components carry no per-row value on any path.</li><li><strong>Table-storage defaults</strong>: required defaults and bundle <code>with</code> factories produce a fresh table per row; other storages share one resolved value across a batch.</li><li><strong>Relationship behaviors</strong>: sparse instances route to the relationship store (the archetype only carries the container marker); exclusive relationships evict the prior sibling; reverse-indexed relationships read the old value before unlinking and link after the new value is written; <code>cascadeDelete</code> recursively despawns sources when their target despawns.</li><li><strong>Dirty tracking</strong>: value writes mark the component column dirty; placements and moves mark the archetype dirty.</li><li><strong>Observer hygiene</strong>: per-entity observers never survive into a recycled slot.</li><li><strong>Reservation accounting</strong>: staged moves reserve destination capacity so drains do not reallocate mid-pass.</li></ul>',45)])])}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
